import {
  Dropdown,
  DropdownTrigger,
  DropdownPopover,
  DropdownGroup,
  DropdownItem,
} from "../../base/dropdown/dropdown";
export interface ConversationActionsProps {
  transcript: string;
  onExport?: () => void;
  onToggleUnread?: () => void;
  onDelete?: () => void;
  disabled?: boolean;
}
const actionClasses =
  "flex size-7 shrink-0 items-center justify-center rounded-md text-foreground-icon-secondary transition-colors duration-150 ease hover:bg-background-primary-hover hover:text-foreground-icon-primary disabled:cursor-not-allowed disabled:opacity-40 [&_svg]:size-[18px]";
export function ConversationActions({
  transcript,
  onExport,
  onToggleUnread,
  onDelete,
  disabled = false,
}: ConversationActionsProps) {
  const [open, setOpen] = useState(false),
    [copied, setCopied] = useState(false);
  useEffect(() => {
    if (copied) {
      const timer = setTimeout(() => setCopied(false), 1600);
      return () => clearTimeout(timer);
    }
  }, [copied]);
  const share = async () => {
    if (!transcript) return;
    try {
      if (navigator.share) {
        await navigator.share({ text: transcript });
        return;
      }
      await navigator.clipboard.writeText(transcript);
      setCopied(true);
    } catch {}
  };
  const choose = (action?: () => void) => {
    setOpen(false);
    action?.();
  };
  return (
    <div className="ms-auto flex shrink-0 items-center gap-0.5">
      <IconButton
        unstyled
        icon={copied ? RiCheckLine : RiUploadLine}
        disabled={disabled}
        aria-label={copied ? "Transcript copied" : "Share chat"}
        title={copied ? "Transcript copied" : "Share chat"}
        onClick={() => void share()}
        className={actionClasses}
      />
      <Dropdown isOpen={open} onOpenChange={setOpen}>
        <DropdownTrigger
          isDisabled={disabled}
          aria-label="More actions for this chat"
          className={actionClasses}
        >
          <RiMoreFill className="size-[18px]" />
        </DropdownTrigger>
        <DropdownPopover
          aria-label="More actions for this chat"
          placement="bottom end"
          className="w-[190px] p-2"
        >
          <DropdownGroup>
            <DropdownItem onSelect={() => choose(onExport)} className="px-2 py-1.5">
              <span className="text-body-medium text-text-primary">Export chats</span>
            </DropdownItem>
            <DropdownItem onSelect={() => choose(onToggleUnread)} className="px-2 py-1.5">
              <span className="text-body-medium text-text-primary">Mark as unread</span>
            </DropdownItem>
            <DropdownItem onSelect={() => choose(onDelete)} className="px-2 py-1.5">
              <span className="text-body-medium text-text-error-primary">Delete chat</span>
            </DropdownItem>
          </DropdownGroup>
        </DropdownPopover>
      </Dropdown>
    </div>
  );
}

