      aria-label={`${installed.includes(item.id) ? (primary ? "Remove" : "View added") : "Add"} ${item.name}`}
      onClick={() => (installed.includes(item.id) && !primary ? open(item) : install(item))}
    >
      {installed.includes(item.id) ? (primary ? "Remove" : "Added") : "Add"}
    </Button>
