                    </CardSurface>
                  </section>
                )}
                <section className="flex flex-col gap-1">
                  <p className="px-3 text-body-2-medium text-text-secondary">Details</p>
                  <CardSurface padding="uniform" className="grid grid-cols-2 gap-4">
                    {[
                      ["Category", selected.category],
                      [
                        "Includes",
                        selected.skill ? "1 skill" : selected.kind === "bot" ? "Agent" : "Plugin",
                      ],
                      ["Availability", "Public"],
                    ].map(([label, value]) => (
                      <div key={label} className="flex flex-col gap-1">
                        <span className="text-body-2-regular text-text-secondary">{label}</span>
                        <span className="text-body-regular text-text-primary">{value}</span>
                      </div>
                    ))}
                  </CardSurface>
                </section>
              </>
            ) : category === "Discover" ? (
              <>
                <MarketplaceSection
                  title="Meet your next teammate"
                  onViewAll={() => changeCategory("Bots")}
                >
                  <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
                    {bots.slice(0, 4).map((item) => (
                      <Button
                        unstyled
                        key={item.id}
                        aria-label={`View ${item.name}`}
                        onClick={() => open(item)}
                        className={`${cardSurfaceClasses({ padding: "none" })} flex min-w-0 flex-col items-center gap-2 px-2 py-4 text-center outline-none transition-colors hover:bg-background-tertiary-default focus-visible:ring-2 focus-visible:ring-border-focus-ring`}
                      >
                        <MarketplaceIcon item={item} featured />
                        <span className="flex flex-col gap-1">
                          <span className="text-body-2-medium text-text-primary">{item.name}</span>
                          <span className="text-caption-1-regular text-text-secondary">
                            {item.category}
                          </span>
                        </span>
                      </Button>
                    ))}
                  </div>
                </MarketplaceSection>
                <MarketplaceSection
                  title="Tools for your workflow"
                  onViewAll={() => changeCategory("Plugins")}
                >
                  {grid(plugins.filter((i) => !i.installed).slice(0, 4))}
                </MarketplaceSection>
                <MarketplaceSection title="Everyday essentials">
                  {grid(plugins.filter((i) => i.installed))}
                </MarketplaceSection>
              </>
            ) : (
              <MarketplaceSection
                title={
                  category === "Plugins"
                    ? "Explore plugins"
                    : category === "Bots"
                      ? "Find your next teammate"
                      : "Added to your workspace"
                }
              >
                {grid(
                  category === "Plugins"
                    ? plugins
                    : category === "Bots"
                      ? bots
                      : filtered.filter((i) => installed.includes(i.id)),
                )}
              </MarketplaceSection>
            )}
            {!selected && filtered.length === 0 && (
              <p className="py-8 text-center text-body-regular text-text-secondary">
                No results found
              </p>
            )}
          </div>
        </div>
      </div>
    </>
  );
}
