"use client";
import {
  RiChatAiLine,
  RiDashboardLine,
  RiLayoutGridLine,
  RiLoginBoxLine,
  RiUserAddLine,
} from "@remixicon/react";
import { type ReactNode, useState, useEffect } from "react";
import { Button } from "../../base/buttons/button";
import { CardSurface } from "../charts/card-surface";
import { ConversationHistory, type ConversationThread } from "../conversation/conversation-history";
import { ConversationActions } from "../conversation/conversation-actions";
import type { ConversationMessage } from "./conversation-state";
import { SimpleComposer, type SimpleComposerProps } from "../composer/simple-composer";
import { ConversationMessages } from "./conversation-messages";
import { ConversationTopBar } from "./conversation-top-bar";
import { useConversationState, type ConversationAdapter } from "./conversation-state";
import { TemplateShell, type TemplateShellProps } from "./template-shell";
const STARTER_NAV = [
  { key: "chat", label: "Chat", icon: RiChatAiLine, href: "#" },
  { key: "dashboard", label: "Dashboard", icon: RiDashboardLine, href: "/templates/dashboard/" },
  {
    key: "components",
    label: "Components and Blocks",
    icon: RiLayoutGridLine,
    href: "/components/",
  },
  { key: "signin", label: "Sign in", icon: RiLoginBoxLine, href: "#" },
  { key: "signup", label: "Sign up", icon: RiUserAddLine, href: "#" },
];
export interface ChatStarterTemplateProps
  extends Pick<TemplateShellProps, "contained" | "className" | "account" | "team"> {
  onSend?: ConversationAdapter;
  showSetup?: boolean;
  setupTitle?: string;
  setupContent?: ReactNode;
  demoDescription?: string;
  /** Scripted demo content; live adapters bypass the demo schedule. */
  demoReply?: string | ((message: string) => string);
  persistHistory?: boolean;
  storageKey?: string;
  composer?: Omit<
    SimpleComposerProps,
    "value" | "onValueChange" | "onSubmit" | "onStop" | "busy" | "messageCount"
  >;
}
export function ChatStarterTemplate({
  onSend,
  composer,
  showSetup = !onSend,
  setupTitle = "Connect an assistant to start",
  setupContent,
  persistHistory = true,
  storageKey = "zeus:chat-starter:v1",
  demoReply = "This starter gives you a conversation view, reusable controls and a place to connect your own assistant. In this demo, replies are local examples.",
  demoDescription = "Demo mode: the answers are scripted. Connect your assistant for live replies.",
  ...shell
}: ChatStarterTemplateProps = {}) {
  const [setup, setSetup] = useState(showSetup);
  useEffect(() => {
    if (!showSetup) setSetup(false);
  }, [showSetup]);
  const conversation = useConversationState({
    onSend,
    demoReply,
    demoTiming: {
      thinkingMs: 700,
      chunkMs: 28,
      wordsPerChunk: 1,
      sentencePauseMultiplier: 1,
      paragraphPauseMultiplier: 1,
    },
  });
  const [threads, setThreads] = useState<
    (ConversationThread & { messages: ConversationMessage[] })[]
  >([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [historyLoaded, setHistoryLoaded] = useState(false);
  useEffect(() => {
    if (persistHistory) {
      try {
        const saved = JSON.parse(localStorage.getItem(storageKey) ?? "null");
        if (saved && Array.isArray(saved.threads)) {
          const valid = saved.threads.filter(
            (t: unknown): t is ConversationThread & { messages: ConversationMessage[] } => {
              if (!t || typeof t !== "object") return false;
              const row = t as Record<string, unknown>;
              return (
                typeof row.id === "string" &&
                typeof row.title === "string" &&
                Array.isArray(row.messages) &&
                row.messages.every(
                  (m) =>
                    m &&
                    typeof m.id === "string" &&
                    (m.role === "user" || m.role === "assistant") &&
                    typeof m.content === "string",
                )
              );
            },
          );
          setThreads(valid);
          const active = valid.find((t: ConversationThread) => t.id === saved.activeId);
          if (active) {
            setActiveId(active.id);
            conversation.reset(active.messages);
          }
          if (valid.length) setSetup(false);
        }
      } catch {}
    }
    setHistoryLoaded(true);
  }, [persistHistory, storageKey]);
  useEffect(() => {
    if (!historyLoaded || !conversation.messages.length) return;
    const id = activeId ?? `chat-${Date.now()}`;
    if (!activeId) setActiveId(id);
    const title =
      conversation.messages.find((m) => m.role === "user")?.content.slice(0, 80) ?? "New chat";
    setThreads((old) =>
      old.some((t) => t.id === id)
        ? old.map((t) => (t.id === id ? { ...t, title, messages: conversation.messages } : t))
        : [{ id, title, messages: conversation.messages }, ...old],
    );
  }, [conversation.messages, activeId, historyLoaded]);
  useEffect(() => {
    if (historyLoaded && persistHistory) {
      try {
        localStorage.setItem(storageKey, JSON.stringify({ threads, activeId }));
      } catch {}
    }
  }, [threads, activeId, historyLoaded, persistHistory, storageKey]);
  const newChat = () => {
    setActiveId(null);
    conversation.reset();
  };
  const selectChat = (id: string) => {
    const thread = threads.find((t) => t.id === id);
    if (!thread) return;
    setActiveId(id);
    conversation.reset(thread.messages);
    setThreads((old) => old.map((t) => (t.id === id ? { ...t, unread: false } : t)));
  };
  const exportChats = () => {
    if (!threads.length) return;
    const url = URL.createObjectURL(
      new Blob([JSON.stringify(threads, null, 2)], { type: "application/json" }),
    );
    const link = document.createElement("a");
    link.href = url;
    link.download = "conversations.json";
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 0);
  };
  const title = threads.find((t) => t.id === activeId)?.title ?? "New chat";
  const history = (
    <ConversationHistory
      threads={threads}
      activeId={activeId}
      account={shell.account}
      onNew={newChat}
      onSelect={selectChat}
      onExport={exportChats}
      className="hidden xl:flex"
    />
  );
  const suggestions = [
    "Explain what this starter does",
    "Write a product update in three sentences",
    "Give me five names for a scheduling app",
  ];
  return (
    <TemplateShell
      {...shell}
      variant="workspace"
      title={title}
      panel={!setup ? history : undefined}
      selected="chat"
      navigationItems={STARTER_NAV}
      workspaceHeader={({ onOpenNavigation, navigationTriggerRef, navigationOpen }) => (
        <ConversationTopBar
          variant="plain"
          shareDisabled={!conversation.messages.length}
          title={title}
          actions={
            <ConversationActions
              transcript={conversation.messages
                .map((m) => `${m.role === "user" ? "You" : "Assistant"}: ${m.content}`)
                .join("\n\n")}
              disabled={!conversation.messages.length}
              onExport={exportChats}
              onToggleUnread={() =>
                setThreads((old) =>
                  old.map((t) => (t.id === activeId ? { ...t, unread: !t.unread } : t)),
                )
              }
              onDelete={() => {
                setThreads((old) => old.filter((t) => t.id !== activeId));
                newChat();
              }}
            />
          }
          onOpenNavigation={onOpenNavigation}
          navigationTriggerRef={navigationTriggerRef}
          navigationOpen={navigationOpen}
          className="absolute inset-x-0 top-0 z-10 h-12 items-center px-4 pt-[7px]"
        />
      )}
    >
      {setup ? (
        <div className="flex min-h-0 flex-1 items-center justify-center overflow-y-auto p-6">
          <CardSurface
            tone="primary"
            padding="none"
            className="flex max-w-md flex-col gap-3 p-6 shadow-card"
          >
            <h2 className="text-headline-medium text-text-primary">{setupTitle}</h2>
            {setupContent ?? (
              <>
                <p className="text-body-regular text-text-secondary">
                  The chat is ready. Connect a model provider in your application to receive live
                  answers.
                </p>
                <ol className="flex list-decimal flex-col gap-1.5 ps-5 text-body-regular text-text-secondary">
                  <li>Choose a model provider for your application.</li>
                  <li>Keep its API key in your application’s environment.</li>
                  <li>Connect the chat’s send callback to your assistant.</li>
                </ol>
                <p className="text-caption-1-regular text-text-tertiary">
                  You can explore the interface now with local example replies.
                </p>
              </>
            )}
            <Button className="w-full" onClick={() => setSetup(false)}>
              Skip, show me the demo
            </Button>
          </CardSurface>
        </div>
      ) : (
        <>
          {conversation.messages.length ? (
            <ConversationMessages variant="plain" messages={conversation.messages} />
          ) : (
            <div className="flex min-h-0 flex-1 items-center justify-center overflow-y-auto">
              <div className="mx-auto flex w-full max-w-3xl flex-col items-center gap-4 px-4 pt-[72px] pb-6 text-center">
                <div className="flex flex-col gap-1">
                  <h2 className="text-title-2-medium text-text-primary">What can I help with?</h2>
                  <p className="text-body-regular text-text-secondary">
                    {onSend ? "Start a conversation with your assistant." : demoDescription}
                  </p>
                </div>
                <div className="flex flex-wrap justify-center gap-2">
                  {suggestions.map((s) => (
                    <Button
                      unstyled
                      key={s}
                      className="rounded-full bg-background-primary-default px-3.5 py-2 text-body-regular text-text-secondary shadow-xs hover:bg-background-primary-hover"
                      onClick={() => void conversation.send(s)}
                    >
                      {s}
                    </Button>
                  ))}
                </div>
              </div>
            </div>
          )}
          {conversation.error && (
            <p role="alert" className="px-4 text-body-regular text-status-rose-text">
              {conversation.error}
            </p>
          )}
          <div className="shrink-0 px-3 pb-3">
            <div className="mx-auto w-full max-w-3xl">
              <SimpleComposer
                {...composer}
                value={conversation.input}
                onValueChange={conversation.setInput}
                onSubmit={(text) => void conversation.send(text)}
                busy={conversation.busy}
                onStop={conversation.stop}
                provider={composer?.provider ?? (onSend ? "Connected" : "Demo mode")}
                messageCount={conversation.messages.length}
              />
            </div>
          </div>
        </>
      )}
    </TemplateShell>
  );
}

