  messages: ConversationMessage[];
  agentLabel?: string;
  avatar?: ReactNode;
  variant?: "bubble" | "plain";
  renderAuthor?: (
    message: ConversationMessage,
  ) => { label: string; avatar?: ReactNode; onSelect?: () => void } | undefined;
}) {
  const scroll = useRef<HTMLDivElement>(null),
    follow = useRef(true);
  useLayoutEffect(() => {
    if (follow.current && scroll.current) scroll.current.scrollTop = scroll.current.scrollHeight;
  }, [messages]);
  return (
    <div
      ref={scroll}
      onScroll={(e) => {
        const el = e.currentTarget;
        follow.current = el.scrollHeight - el.scrollTop - el.clientHeight <= 40;
      }}
      aria-label="Messages"
      tabIndex={0}
      className={
        variant === "plain"
          ? "min-h-0 flex-1 overflow-y-auto scroll-smooth outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-border-focus-ring"
          : "min-h-0 flex-1 overflow-y-auto overscroll-contain px-3 pt-2 pb-4 outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-border-focus-ring [scrollbar-width:none]"
      }
    >
      {variant === "bubble" && (
        <div className="mt-3 mb-4 flex justify-center">
          <span className="rounded-full bg-background-tertiary-default px-[7px] py-1 text-body-2-medium text-text-secondary">
            Today
          </span>
        </div>
      )}
      <div
        className={
          variant === "plain"
            ? "mx-auto flex w-full max-w-3xl flex-col gap-5 px-4 pt-[72px] pb-6"
            : "flex flex-col gap-3"
        }
      >
        {messages.map((m) => {
          const Tag = variant === "bubble" && m.role === "assistant" ? "article" : "div";
          const author =
            renderAuthor?.(m) ??
            (agentLabel ? { label: agentLabel, avatar, onSelect: undefined } : undefined);
          return (
            <Tag
              key={m.id}
              className={
                m.role === "user"
                  ? variant === "plain"
                    ? "ms-auto w-fit max-w-[75%] rounded-2xl bg-background-primary-default px-3 py-[11px] text-body-regular break-words whitespace-pre-wrap text-text-primary shadow-card"
                    : "ms-auto w-fit max-w-[520px] rounded-[20px] bg-background-primary-default px-3 py-3 text-body-regular whitespace-pre-line text-text-primary"
                  : variant === "plain"
                    ? "group/message flex flex-col gap-1 px-1"
                    : "group me-auto w-fit max-w-[520px]"
              }
            >
              {m.role === "user" ? (
                m.content
              ) : (
                <>
                  {m.content && (
                    <div
                      className={
                        variant === "plain"
                          ? "flex flex-col gap-3 text-body-regular text-text-primary"
                          : "flex flex-col gap-3 rounded-[20px] bg-background-tertiary-default p-3 text-body-regular text-text-primary"
                      }
                    >
                      {m.content
                        .split("\n\n")
                        .filter((part) => part.trim())
                        .map((part, i) => (
                          <motion.p
                            key={i}
                            initial={{ opacity: 0, filter: "blur(5px)", y: 4 }}
                            animate={{ opacity: 1, filter: "blur(0px)", y: 0 }}
                            transition={{ duration: 0.42, ease: [0.22, 0.61, 0.36, 1] }}
                            className="whitespace-pre-wrap break-words"
                          >
                            {part}
                          </motion.p>
                        ))}
                    </div>
                  )}
                  {author && (
                    <ConversationAuthor
                      {...author}
                      thinking={m.status === "thinking"}
                      actions={
                        variant === "bubble" &&
                        m.content &&
                        m.status !== "thinking" &&
                        m.status !== "streaming" ? (
                          <div
                            aria-label="Message actions"
                            className="mt-1 flex shrink-0 items-center gap-1 opacity-0 transition-opacity duration-150 group-hover:opacity-100 group-focus-within:opacity-100"
                          >
                            <ConversationFeedback
                              text={m.content}
                              variant="compact"
                              showRetry={false}
                              onRetry={() => {}}
                            />
                          </div>
                        ) : undefined
                      }
                    />
                  )}
                  {variant === "plain" && m.content && m.status !== "thinking" && m.status !== "streaming" && (
                    <PlainMessageActions text={m.content} />
                  )}
                </>
              )}
            </Tag>
          );
        })}
      </div>
    </div>
  );
}

function PlainMessageActions({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const style =
    "flex size-7 cursor-pointer items-center justify-center rounded-md text-foreground-icon-tertiary transition-colors hover:bg-background-primary-default hover:text-foreground-icon-secondary";
  return (
    <div className="flex items-center gap-1 opacity-0 transition-opacity duration-150 group-hover/message:opacity-100 focus-within:opacity-100">
      <IconButton
        size="small"
        unstyled
        icon={copied ? RiCheckLine : RiFileCopyLine}
        className={style}
        aria-label={copied ? "Copied message" : "Copy message"}
        title="Copy message"
        onClick={async () => {
          try {
            await navigator.clipboard.writeText(text);
            setCopied(true);
          } catch {
            setCopied(false);
          }
        }}
      />
      <IconButton
        size="small"
        unstyled
        icon={RiVolumeUpLine}
        className={style}
        aria-label="Read aloud"
        title="Read aloud"
        onClick={() => {
          if (typeof speechSynthesis !== "undefined") {
            speechSynthesis.cancel();
            speechSynthesis.speak(new SpeechSynthesisUtterance(text));
          }
        }}
      />
      <span className="ms-1 text-caption-1-regular text-text-tertiary">just now</span>
    </div>
  );
}

// @zeus-internal
"use client";
import { useEffect, useRef, useState } from "react";
export interface ConversationMessage {
  id: string;
  role: "user" | "assistant";
  content: string;
  agentId?: string;
  status?: "thinking" | "streaming" | "complete";
}
export type ConversationAdapter = (
  message: string,
  options: { signal: AbortSignal; messages: ConversationMessage[]; agentId?: string },
) => Promise<string>;
export interface ConversationDemoTiming {
  thinkingMs: number;
  firstParticipantThinkingMs?: number;
  chunkMs: number;
  wordsPerChunk?: number;
  sentencePauseMultiplier?: number;
  paragraphPauseMultiplier?: number;
}
export function settleConversationMessages(messages: ConversationMessage[]): ConversationMessage[] {
  return messages
    .filter((m) => m.role !== "assistant" || m.content.trim() || !m.status)
    .map((m) => (m.status && m.status !== "complete" ? { ...m, status: "complete" as const } : m));
}
function waitForDemo(ms: number, signal: AbortSignal) {
  return new Promise<void>((resolve, reject) => {
    if (signal.aborted) {
      reject(new DOMException("Aborted", "AbortError"));
      return;
    }
    const timer = setTimeout(() => {
      signal.removeEventListener("abort", cancel);
      resolve();
    }, ms);
    const cancel = () => {
      clearTimeout(timer);
      signal.removeEventListener("abort", cancel);
      reject(new DOMException("Aborted", "AbortError"));
    };
    signal.addEventListener("abort", cancel, { once: true });
  });
}
export function useConversationState({
  initialMessages = [],
  onSend,
  demoReply,
  agentId,
  participants,
  demoTiming,
}: {
  initialMessages?: ConversationMessage[];
  onSend?: ConversationAdapter;
  demoReply: string | ((message: string) => string);
  agentId?: string;
  participants?: { agentId: string; demoReply: string }[];
  demoTiming?: ConversationDemoTiming;
}) {
  const [messages, setMessages] = useState(initialMessages),
    [input, setInput] = useState(""),
    [busy, setBusy] = useState(false),
    [error, setError] = useState("");
  const request = useRef<AbortController | null>(null),
    sequence = useRef(0);
  const stop = () => {
    sequence.current++;
    request.current?.abort();
    setMessages(settleConversationMessages);
    setBusy(false);
  };
  useEffect(() => () => request.current?.abort(), []);
  const reset = (next: ConversationMessage[] = []) => {
    stop();
    setMessages(settleConversationMessages(next));
    setInput("");
    setError("");
  };
  const send = async (text: string) => {
    const value = text.trim();
    if (!value || busy) return;
    let id = ++sequence.current;
    const existingIds = new Set(messages.map((message) => message.id));
    while (
      existingIds.has(`user-${id}`) ||
      [...existingIds].some(
        (existing) => existing === `assistant-${id}` || existing.startsWith(`assistant-${id}-`),
      )
    )
      id = ++sequence.current;
    const controller = new AbortController();
    request.current = controller;
    const next = [...messages, { id: `user-${id}`, role: "user" as const, content: value }];
    setMessages(settleConversationMessages(next));
    setInput("");
    setError("");
    setBusy(true);
    try {
      const replies = participants?.length
        ? participants
        : [{ agentId, demoReply: typeof demoReply === "function" ? demoReply(value) : demoReply }];
      let context = next;
      for (let index = 0; index < replies.length; index++) {
        const participant = replies[index];
        const replyId = `assistant-${id}${replies.length > 1 ? `-${index}` : ""}`;
        if (demoTiming && !onSend) {
          const prefix = context;
          const draft: ConversationMessage = {
            id: replyId,
            role: "assistant",
            content: "",
            agentId: participant.agentId,
            status: "thinking",
          };
          setMessages([...prefix, draft]);
          await waitForDemo(
            index === 0 && replies.length > 1
              ? (demoTiming.firstParticipantThinkingMs ?? demoTiming.thinkingMs)
              : demoTiming.thinkingMs,
            controller.signal,
          );
          const words = participant.demoReply.match(/\S+(?:\s+|$)/g) ?? [];
          let content = "",
            delay = demoTiming.chunkMs;
          const chunkSize = Math.max(1, Math.floor(demoTiming.wordsPerChunk ?? 2));
          for (let cursor = 0; cursor < words.length; cursor += chunkSize) {
            await waitForDemo(delay, controller.signal);
            if (sequence.current !== id || controller.signal.aborted) return;
            content += words.slice(cursor, cursor + chunkSize).join("");
            setMessages([...prefix, { ...draft, content, status: "streaming" }]);
            delay =
              demoTiming.chunkMs *
              (/\n\n\s*$/.test(content)
                ? (demoTiming.paragraphPauseMultiplier ?? 3)
                : /[.!?]\s*$/.test(content)
                  ? (demoTiming.sentencePauseMultiplier ?? 2)
                  : 1);
          }
          if (sequence.current !== id || controller.signal.aborted) return;
          context = [...prefix, { ...draft, content, status: "complete" }];
        } else {
          const reply = onSend
            ? await onSend(value, {
                signal: controller.signal,
                messages: context,
                agentId: participant.agentId,
              })
            : participant.demoReply;
          if (sequence.current !== id || controller.signal.aborted) return;
          context = [
            ...context,
            {
              id: replyId,
              role: "assistant" as const,
              content: reply,
              agentId: participant.agentId,
              status: "complete",
            },
          ];
        }
        setMessages(context);
      }
      setBusy(false);
    } catch (e) {
      if (sequence.current !== id || controller.signal.aborted) return;
      setError(e instanceof Error ? e.message : "Could not send the message. Try again.");
      setBusy(false);
    }
  };
  return { messages, input, setInput, busy, error, send, stop, reset };
}

