export interface TemplateTopBarProps {
  variant?: "dashboard" | "workspace";
  headerClassName?: string;
  compactTitle?: string;
  projectName?: string;
  onOpenPanel?: () => void;
  panelActionLabel?: string;
  title: string;
  heading?: string;
  action?: string;
